// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

// Abstract contract

 abstract contract Bank {

    uint public balance;

    // Function with definition

    function getBalance() public view returns (uint) {

        return balance;

    }

    // Function with declaration only (abstract function)

    function deposit(uint amount) public virtual;

}

// Child contract

contract MyBank is Bank {

    function deposit(uint amount) public override {

        balance = balance + amount;

    }

}

