// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

contract DrugSupplyChain {
    address public owner;

    enum Status { Registered, Shipped, Delivered, Sold }
    struct Drug {
        string name;
        string batchNumber;
        uint expiryDate;
        address currentOwner;
        Status status;
        address[] ownersHistory;
    }

    mapping(uint => Drug) public drugs;
    mapping(address => bool) public stakeholders; // manufacturers, suppliers, etc.
    uint public drugCount;

    event DrugRegistered(uint id, string name, string batchNumber, address manufacturer);
    event StatusUpdated(uint id, Status newStatus, address updatedBy);
    event OwnershipTransferred(uint id, address from, address to);

    modifier onlyStakeholder() {
        require(stakeholders[msg.sender], "Not a registered stakeholder");
        _;
    }

    modifier onlyCurrentOwner(uint _id) {
        require(drugs[_id].currentOwner == msg.sender, "Not current owner");
        _;
    }

    constructor() {
        owner = msg.sender;
    }

    function registerStakeholder(address _stakeholder) public {
        require(msg.sender == owner, "Only owner can register");
        stakeholders[_stakeholder] = true;
    }

    function registerDrug(string memory _name, string memory _batchNumber, uint _expiryDate) public onlyStakeholder {
        drugCount++;
        drugs[drugCount] = Drug(_name, _batchNumber, _expiryDate, msg.sender, Status.Registered, new address[](0));
        drugs[drugCount].ownersHistory.push(msg.sender);
        emit DrugRegistered(drugCount, _name, _batchNumber, msg.sender);
    }

    function updateStatus(uint _id, Status _newStatus) public onlyCurrentOwner(_id) {
        drugs[_id].status = _newStatus;
        emit StatusUpdated(_id, _newStatus, msg.sender);
    }

    function transferOwnership(uint _id, address _newOwner) public onlyCurrentOwner(_id) {
        require(_newOwner != address(0), "Invalid address");
        require(stakeholders[_newOwner], "New owner not registered");
        address prevOwner = drugs[_id].currentOwner;
        drugs[_id].currentOwner = _newOwner;
        drugs[_id].ownersHistory.push(_newOwner);
        emit OwnershipTransferred(_id, prevOwner, _newOwner);
    }

    function getDrugDetails(uint _id) public view returns (
        string memory name, string memory batchNumber, uint expiryDate,
        address currentOwner, Status status, address[] memory history
    ) {
        Drug storage drug = drugs[_id];
        return (drug.name, drug.batchNumber, drug.expiryDate, drug.currentOwner, drug.status, drug.ownersHistory);
    }
}
